def compute(vars):
    old_price = vars["v2"]
    new_price = vars["v1"]
    change = new_price - old_price

    return {
        "value": change,
        "trace": {
            "old_price": old_price,
            "new_price": new_price,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "price per troy ounce"
            }
        }
    }
